//! Zed extension entry point.
//!
//! The grammar comes from `editors/grammars/tree-sitter-yashy/grammar.js`,
//! generated by `yashyc tokens --grammar editors`. All language intelligence
//! comes from `yashyc lsp --stdio`; this crate only registers both with Zed.

use zed_extension_api::{self as zed, LanguageServerId, Result};

struct YashyExtension;

impl zed::Extension for YashyExtension {
    fn new() -> Self {
        Self
    }

    fn language_server_command(
        &mut self,
        _id: &LanguageServerId,
        _worktree: &zed::Worktree,
    ) -> Result<zed::Command> {
        Ok(zed::Command {
            command: "yashyc".to_string(),
            args: vec!["lsp".to_string(), "--stdio".to_string()],
            env: Vec::new(),
        })
    }
}

zed::register_extension!(YashyExtension);
